import '../../src/styles/index.css';
import '../../src/styles/atelier.css';
import React,{useState,useRef} from 'react';import {createRoot} from 'react-dom/client';import CeritaPanel from '../../src/components/CeritaPanel.jsx';import ViridariumTemplate from '../../src/components/templates/viridarium/ViridariumTemplate.jsx';import {UIProvider} from '../../src/context/UIContext.jsx';import {api} from '../../src/api/client.js';import {mergePreviewOverride} from '../../src/utils/mergePreviewOverride.js';
const initial={id:'story-ui-check',themeId:'garden-canvas',themeSettings:{mainStory:'Kami memilih berjalan bersama.',characterSettings:{mode:'default'}},coupleProfile:{brideName:'A',groomName:'B'},invitationFeatures:{storyEnabled:true,timelineEnabled:true},timelineStories:[{id:'one',title:'Pertemuan pertama',date:'2022-06-01',description:'Dari percakapan sederhana, kisah ini bermula.'},{id:'two',title:'Lamaran',date:'2025-09-01',description:'Di hadapan keluarga, kami memilih melangkah bersama.'}]};
api.patch=async(url,payload)=>({data:url.includes('/theme')?{themeSettings:{...initial.themeSettings,...payload}}:{features:payload}});
function App(){const [inv,setInv]=useState(initial),[patch,setPatch]=useState(null);const wrap=useRef(null);function open(){const w=wrap.current.querySelector('iframe').contentWindow;w.document.querySelector('#open').click();setTimeout(()=>w.document.querySelector('.section-dot[data-scene="cerita"]').click(),4000)}return <UIProvider><div className="atelier-app" style={{display:'grid',gridTemplateColumns:'420px 390px',gap:30}}><div className="panel" style={{padding:20,background:'#faf8ef'}}><CeritaPanel invitation={inv} onUpdated={setInv} onLivePreview={setPatch}/><pre>{inv.timelineStories.length} bab tersimpan; narasi: {inv.themeSettings.mainStory}</pre></div><div><button onClick={open}>Buka cerita di preview</button><div ref={wrap} style={{width:390,height:844,position:'relative'}}><ViridariumTemplate invitation={mergePreviewOverride(inv,patch)}/></div></div></div></UIProvider>}
createRoot(document.getElementById('root')).render(<App/>);
